"""Display one already-computed secondary alternative without changing the registered endpoint."""
import argparse,hashlib,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--revision',required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
paths=['artifacts/irac_colour_resource_resumed_20261012/all_records.json','artifacts/irac_colour_resource_resumed_verification_20261012/verification.json','artifacts/native_glimpse_association_20261012/evidence_cards.json','artifacts/irac_colour_resource_resumed_20261012/summary.json']
b={name:subprocess.check_output(['git','show',a.revision+':'+name],cwd=ROOT) for name in paths};v=json.loads(b[paths[1]]);assert v['verified'] and v['all_records_sha256']==hashlib.sha256(b[paths[0]]).hexdigest()
name='SSTGLMC G353.4284-00.3731';rows=[x for x in json.loads(b[paths[0]]) if x['designation']==name and x['kind']=='Catalog'];assert len(rows)==1;r=rows[0];c12=next(x for x in r['colours'] if (x['band_a'],x['band_b'])==('3_6','4_5'));c23=next(x for x in r['colours'] if (x['band_a'],x['band_b'])==('4_5','5_8'))
assert c12['colour_mag']==1 and c23['colour_mag']==.79 and r['decision']['four_band_photometric_availability'] and r['decision']['central_necessary_colours'] is True and not r['decision']['robust_necessary_colour_support'] and r['native_sqf_4_5']=='0'
card=next(x for x in json.loads(b[paths[2]])['evidence_cases'] if x['case_id']==r['case_id']);native=next(x for x in card['all_native_alternatives'] if x['kind']=='Catalog' and x['designation']==name and x['cntr']==r['cntr']);assert native['supported_visit_matches']=='0' and card['total_supported_visits']==6
assert json.loads(b[paths[3]])['robust_necessary_support']==0
record=dict(schema='already-computed-secondary-irac-alternative/1',verified_source_binding=True,source_revision=a.revision,case_id=r['case_id'],native_source_id=name,native_cntr=r['cntr'],role='post-read display of a retained secondary alternative, not replacement of the three fixed best counterparts',colour_36_45=c12,colour_45_58=c23,four_band_photometric_availability=True,central_necessary_colours=True,robust_necessary_colour_support=False,full_standard_classification='not_evaluated',native_45_quality_flag='0',other_band_quality_flags='not_retained_by_native_excerpt',matched_visits=0,supported_visits=6,clump_separation_arcsec=float(native['clump_separation_arcsec']),physical_stage='unknown',physical_membership='unestablished',birth_status='not_established',new_discovery=False,original_primary_and_models_unchanged=True,source_blobs=[dict(path=k,revision=a.revision,bytes=len(v),sha256=hashlib.sha256(v).hexdigest()) for k,v in b.items()])
with a.output.open('x') as f:json.dump(record,f,indent=2);f.write('\n')
print(json.dumps({k:v for k,v in record.items() if k!='source_blobs'},indent=2))
